scripts.杨瑛的同伴对话.txt:
//和杨瑛的同伴对话

	If ($Clue == 0) @Clue0;
	If ($Clue == 10) @Clue10;
	If ($Clue == 15) @Clue15;
	If ($Clue == 20) @Clue20;
	If ($Clue == 25) @Clue25;
	If ($Clue == 30) @Clue30;
	If ($Clue == 31) @Clue31;
	If ($Clue == 35) @Clue35;
	If ($Clue == 40) @Clue40;
	If ($Clue == 41) @Clue41;
	If ($Clue == 45) @Clue45;
	If ($Clue == 50) @Clue50;
	If ($Clue == 60) @Clue60;
	If ($Clue == 65) @Clue65;
	If ($Clue == 70) @Clue70;
	If ($Clue == 71) @Clue71;
	If ($Clue >= 75) @Cluemore75;
	
@Clue0:
	Say("杨瑛：独孤大哥，我们先去客栈打听打听张姑娘和张少侠的消息。", 39);
	Return;

@Clue10:
	Say("杨瑛：这店小二怎有些怪怪的。", 39);
	Return;

@Clue15:
	Say("杨瑛：我们在成都有个暗口，负责接应的人叫“贺老四”——我们不妨去找他。", 39);
	Return;

@Clue20:
	Say("杨瑛：贺老四是天王帮在成都的接应人，虽然沉默少言，却是个精细人。", 39);
	Return;
	
@Clue25:
	Say("杨瑛：独孤大哥，真是奇怪，为什么客栈的掌柜和小二都说不知道呢？我觉得很可疑，现在去调查谁呢？", 39);
	Choose("独孤剑：我觉得应该查问……","A 店小二","B 吕掌柜", $Choose);
	If ($Choose == 0) @Choose250;
	If ($Choose == 1) @Choose251;
	
  @Choose250:	
	Say("杨瑛：我也觉得是，刚才这个小二就有点支支吾吾……如果独孤大哥想到什么线索，就马上跟我说！", 39);
	Return;
  @Choose251:
  	Say("杨瑛：这个吕掌柜倒也有些古怪，不过我觉得……独孤大哥，如果你想到什么线索，就马上跟我说。", 39);
	Return;
	
@Clue30:
	Say("杨瑛：既然已经知道张姑娘和张少侠的下落，我们不如在客栈休息一晚吧。", 39);
	Return;
	
@Clue31:
	Say("杨瑛：独孤大哥，我们现在去城北找张姑娘。", 39);
	Return;
	
@Clue35:
	Say("杨瑛：独孤大哥，我们现在去城北找张姑娘。", 39);
	Return;
	
@Clue40:
	Say("杨瑛：看来我们上当了……客栈的留书可能是假的。", 39);
	Return;

@Clue41:
	Say("杨瑛：独孤大哥，我觉得这里有些蹊跷……你认为谁最可疑？", 39);
	Choose("独孤剑：我怀疑……","A 贺老四","B 吕掌柜",$Choose);
	If ($Choose == 0) @Choose410;
	If ($Choose == 1) @Choose411;
	
  @Choose410:
  	Say("杨瑛：贺老四……他哪里可疑呢？", 39);
  	Choose("独孤剑：他的……","A 言语","B 表情",$Choose);
    	If ($Choose == 0) @Choose4100;
	If ($Choose == 1) @Choose4101;
    @Choose4100:
    	Say("杨瑛：言语？……对了！我扮成男装之事一般教众根本就不知道，而我换回女子装束也只是在刚刚离开总堂前。贺老四他如何一见到我们，便已知道我便是换回女装的帮主……", 42);
    	Say("独孤剑：而索七是最先离开总堂来到成都的帮中兄弟……", 1);
    	Say("杨瑛：他不可能在我们之前就见过贺老四，也就是说……", 42);
    	Say("独孤剑：贺老四一开始就知道杨姑娘的底细！", 6);
    	Say("杨瑛：对，我们快去找他！", 39);
    	Assign($Clue, 45);
    	Memo("独孤剑发现贺老四的破绽，两人决定调查贺老四。");
    	Return;
    @Choose4101:
    	Say("杨瑛：表情？……贺老四一贯寡言少语，其实为人很精明，是帮中的一个得力兄弟。", 39);
    	Say("独孤剑：看来，我们还得另找线索。", 9);
    	Say("杨瑛：独孤大哥，不必着急。如果你有什么发现，就告诉我。", 39);
    	Return;
  
  @Choose411:
  	Say("杨瑛：吕掌柜……他哪里可疑呢？", 39);
  	Choose("独孤剑：他的……","A 言语","B 表情",$Choose);
    	If ($Choose == 0) @Choose4110;
	If ($Choose == 1) @Choose4111;
    @Choose4110:
    	Say("杨瑛：贺老四说见过张姑娘在客栈投宿，可是这个吕掌柜却始终推说不知道。但他的话却没有什么矛盾之处啊……", 39);
    	Say("独孤剑：看来，我们得另想办法。", 9);
    	Say("杨瑛：独孤大哥，不必着急。如果你有什么发现，就告诉我。", 39);
    	Return;
    @Choose4111:
    	Say("杨瑛：吕掌柜神色确实有些古怪，不过倒是看不出什么破绽。店小二又莫名其妙的死了……", 39);
    	Say("独孤剑：我们应该留意这个吕掌柜。", 1);
    	Say("杨瑛：嗯。对了，独孤大哥，如果有什么发现，就告诉我。", 39);
    	Return;
    	
@Clue45:
	Say("杨瑛：独孤大哥，那我们快去找贺老四！", 39);
	Return;
	
@Clue50:
	Say("杨瑛：独孤大哥，我们在贺老四房间里搜一搜，也许能找到些线索。", 39);
	Return;
	
@Clue60:
	Say("杨瑛：“口”，独孤大哥，你认为这指的是什么呢？", 39);
	
	Choose("独孤剑：这可能指的是……","A 一个地名","B 一个人名",$Choose);
	If ($Choose == 0) @Choose600;
	If ($Choose == 1) @Choose601;

  @Choose600:
	Say("杨瑛：地名？这附近没有与“口”有关的地名……", 39);
	Say("独孤剑：的确让人费解。", 1);
	Say("杨瑛：我们再打听打听。独孤大哥，如果有什么发现，就告诉我。", 39);
	Return;
	
   @Choose601:
	Say("杨瑛：如果是人名，这个“口”字却未免古怪了……", 39);
	Say("独孤剑：贺老四临死之前想给我们留下线索，那……", 1);
	Say("杨瑛：不错，他临死之前也许只写了字的一部分……那会是谁呢？客栈有个吕掌柜，街上的麻婆四……", 39);
	Choose("独孤剑：我想应该是","A 吕掌柜","B 麻婆四",$Choose);
	If ($Choose == 0) @Choose6010;
	If ($Choose == 1) @Choose6011;
	
  @Choose6010:
	Say("杨瑛：不错，这个吕掌柜一直很可疑。不过他一直吞吞吐吐，怎样才能逼他说出真相呢？", 39);
	Return;
	
  @Choose6011:
	Say("杨瑛：麻婆四，我们一直忽略了这个人。对，我们应该调查一下她的底细。", 39);
	Return;

@Clue65:
	Say("杨瑛：独孤大哥，我们先找到吕掌柜的下落。", 39);
	Return;
			
@Clue70:
	Say("杨瑛：……独孤大哥，看来我们想错了。贺兄弟临死时留的可能不是一个“口”字。", 39);
	
	Choose("独孤剑：那“口”指的是","A 地图","B 象声",$Choose);
	If ($Choose == 0) @Choose700;
	If ($Choose == 1) @Choose701;
	
@Choose700:
	Say("杨瑛：地图？可是指的是什么地方呢？", 39);
	Say("独孤剑：我暂时也想不出。", 1);
	Say("杨瑛：独孤大哥，如果你想到什么的话，就告诉我。", 39);
	Return;

@Choose701:
	If ($Talkfangzhang == 1) @Clue75;
	
	Say("杨瑛：指的是一种音，可是到底是什么呢？", 39);
	Say("独孤剑：我暂时也想不出来。", 1);
	Say("杨瑛：独孤大哥，如果你想到什么的话，就告诉我。", 39);
	Assign($Clue, 71);
	Memo("在城郊发现了客栈吕掌柜的尸体，事情更加扑朔迷离了。");
	Memo("从索七那得知贺老四原来并不识字，那么这个神秘的“口”到底代表什么呢？");
	Return;
	
  @Clue75:
	Say("杨瑛：一种音……", 39);
	Say("杨瑛：口，口，正正方方……“方”！“方”，莫非是……", );
	Say("独孤剑：方员外山庄！", 6);
	Say("杨瑛：不错！江湖中传言，方勉就是五色教的教主，难道山庄便是五色教总坛？", 39);
	Say("独孤剑：我们就去闯他一闯！", 5);
	Assign($Clue, 75);
	Memo("在城郊发现了客栈吕掌柜的尸体，事情更加扑朔迷离了。");
	Memo("从索七那得知贺老四原来并不识字，杨瑛忽然想到“口”可能代表的是方的形音。两人决定前往方氏山庄调查。");
	Return;
	
@Clue71:
	Say("杨瑛：……独孤大哥，如果是声音的话，“口”会指的是什么呢？", 39);
	Return;

@Cluemore75:
	Say("杨瑛：独孤大哥，我们去山庄看看。",39);
	Return;

